package com.ftk.tpip.release.domain.model;
import java.time.Instant;import java.util.Objects;
public record VerificationRun(Long id,long workspaceId,long runNo,VerificationRunType runType,VerificationStatus status,int totalCount,int passedCount,int failedCount,String evidenceUri,String resultSummary,Instant startedAt,Instant finishedAt){public VerificationRun{if(id!=null&&id<=0)throw new IllegalArgumentException("id must be positive");if(workspaceId<=0||runNo<0)throw new IllegalArgumentException("invalid verification identity");Objects.requireNonNull(runType);Objects.requireNonNull(status);if(totalCount<0||passedCount<0||failedCount<0||passedCount+failedCount!=totalCount)throw new IllegalArgumentException("verification counts are inconsistent");if(status==VerificationStatus.RUNNING&&(totalCount!=0||finishedAt!=null))throw new IllegalArgumentException("RUNNING verification cannot have final counts");if(status==VerificationStatus.PASSED&&failedCount!=0)throw new IllegalArgumentException("PASSED verification cannot contain failures");if(status!=VerificationStatus.RUNNING&&finishedAt==null)throw new IllegalArgumentException("completed verification requires finishedAt");resultSummary=resultSummary==null?"{}":resultSummary;}}
